class MyCircularDeque {
    private final int[] data;
    private final int capacity;
    private int head;
    private int tail;

    public MyCircularDeque(int k) {
        data = new int[k];
        capacity = k;
    }

    public boolean insertFront(int value) {
        if (isFull()) {
            return false;
        }
        head--;
        data[Math.floorMod(head, capacity)] = value;
        return true;
    }

    public boolean insertLast(int value) {
        if (isFull()) {
            return false;
        }
        data[Math.floorMod(tail, capacity)] = value;
        tail++;
        return true;
    }

    public boolean deleteFront() {
        if (isEmpty()) {
            return false;
        }
        head++;
        return true;
    }

    public boolean deleteLast() {
        if (isEmpty()) {
            return false;
        }
        tail--;
        return true;
    }

    public int getFront() {
        return isEmpty() ? -1 : data[Math.floorMod(head, capacity)];
    }

    public int getRear() {
        return isEmpty() ? -1 : data[Math.floorMod(tail - 1, capacity)];
    }

    public boolean isEmpty() {
        return head == tail;
    }

    public boolean isFull() {
        return tail - head == capacity;
    }
}

class MyCircularDeque {
    private static final class Node {
        int value;
        Node prev;
        Node next;

        Node(int value) {
            this.value = value;
        }
    }

    private final int capacity;
    private final Node head;
    private final Node tail;
    private int size;

    public MyCircularDeque(int k) {
        capacity = k;
        head = new Node(0);
        tail = new Node(0);
        head.next = tail;
        tail.prev = head;
    }

    public boolean insertFront(int value) {
        if (isFull()) {
            return false;
        }
        addAfter(head, new Node(value));
        size++;
        return true;
    }

    public boolean insertLast(int value) {
        if (isFull()) {
            return false;
        }
        addBefore(tail, new Node(value));
        size++;
        return true;
    }

    public boolean deleteFront() {
        if (isEmpty()) {
            return false;
        }
        remove(head.next);
        size--;
        return true;
    }

    public boolean deleteLast() {
        if (isEmpty()) {
            return false;
        }
        remove(tail.prev);
        size--;
        return true;
    }

    public int getFront() {
        return isEmpty() ? -1 : head.next.value;
    }

    public int getRear() {
        return isEmpty() ? -1 : tail.prev.value;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == capacity;
    }

    private void addAfter(Node left, Node node) {
        Node right = left.next;
        node.prev = left;
        node.next = right;
        left.next = node;
        right.prev = node;
    }

    private void addBefore(Node right, Node node) {
        addAfter(right.prev, node);
    }

    private void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }
}

class MyCircularDeque {
    private static final class Cell {
        int value;
        Cell prev;
        Cell next;
    }

    private final int capacity;
    private Cell frontCell;
    private Cell rearCell;
    private int size;

    public MyCircularDeque(int k) {
        capacity = k;
        Cell first = new Cell();
        Cell previous = first;
        for (int i = 1; i < k; i++) {
            Cell cell = new Cell();
            previous.next = cell;
            cell.prev = previous;
            previous = cell;
        }
        previous.next = first;
        first.prev = previous;
        frontCell = first;
        rearCell = first;
    }

    public boolean insertFront(int value) {
        if (isFull()) {
            return false;
        }
        if (!isEmpty()) {
            frontCell = frontCell.prev;
        }
        frontCell.value = value;
        if (isEmpty()) {
            rearCell = frontCell;
        }
        size++;
        return true;
    }

    public boolean insertLast(int value) {
        if (isFull()) {
            return false;
        }
        if (!isEmpty()) {
            rearCell = rearCell.next;
        }
        rearCell.value = value;
        if (isEmpty()) {
            frontCell = rearCell;
        }
        size++;
        return true;
    }

    public boolean deleteFront() {
        if (isEmpty()) {
            return false;
        }
        if (size > 1) {
            frontCell = frontCell.next;
        }
        size--;
        return true;
    }

    public boolean deleteLast() {
        if (isEmpty()) {
            return false;
        }
        if (size > 1) {
            rearCell = rearCell.prev;
        }
        size--;
        return true;
    }

    public int getFront() {
        return isEmpty() ? -1 : frontCell.value;
    }

    public int getRear() {
        return isEmpty() ? -1 : rearCell.value;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public boolean isFull() {
        return size == capacity;
    }
}
